      "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]*$"
    },
    "headerName": {
      "title": "header name",
      "description": "An HTTP header name.",
      "type": "string",
      "pattern": "^[!#$%&'*+.^_`|~0-9A-Za-z-]+$"
    },
    "ruleId": {
      "title": "rule id",
      "description": "A lint rule id: seampact/<rule> or <plugin>/<rule>.",
