          "$ref": "common.schema.json#/$defs/date",
          "$comment": "ADR 0002 section 10"
        },
        "successor": {
          "$ref": "common.schema.json#/$defs/name",
          "$comment": "ADR 0002 section 10",
          "description": "The operation id that replaces this route."
        },
        "$include": {
          "$ref": "common.schema.json#/$defs/include"
        }
      },
      "additionalProperties": false
    },
    "cache": {
      "type": "object",
      "properties": {
        "freshness": {
          "$ref": "common.schema.json#/$defs/name",
          "$comment": "ADR 0002 section 10",
          "description": "A family of conventions.cache.families, or never."
        },
        "anonymous": {
          "enum": [
            "public",
            "private"
          ],
          "$comment": "ADR 0002 section 10"
        },
        "vary": {
          "type": "array",
          "items": {
            "$ref": "common.schema.json#/$defs/headerName"
          },
          "$comment": "ADR 0002 section 10"
        },
        "etag": {
          "type": "boolean",
          "$comment": "ADR 0002 section 10"
        },
        "$include": {
          "$ref": "common.schema.json#/$defs/include"
        }
      },
      "additionalProperties": false
    },
    "paging": {
      "description": "A paging style name, none, or { <style>: { maxLimit, defaultLimit, overLimit, token } }.",
      "if": {
        "type": "string"
      },
      "then": {
        "$ref": "common.schema.json#/$defs/name",
        "enum": [
          "cursor",
          "none"
        ],
        "enumDescriptions": [
          "Declared in api.yaml line 13.",
          "No paging: the whole list in one response."
        ]
      },
      "else": {
        "if": {
          "type": "object"
        },
        "then": {
          "type": "object",
          "properties": {
            "$include": {
              "$ref": "common.schema.json#/$defs/include"
            }
          },
          "propertyNames": {
            "description": "a paging style name (ADR 0002 section 10)",
            "pattern": "^(?:[a-z][A-Za-z0-9_]*|\\$include)$",
            "not": {
              "enum": [
                "__proto__",
                "constructor",
                "prototype"
              ]
            }
          },
          "if": {
            "properties": {
              "$include": true
            },
            "required": [
              "$include"
            ]
          },
          "then": {
            "maxProperties": 2
          },
          "else": {
            "minProperties": 1,
            "maxProperties": 1
          },
          "additionalProperties": {
            "type": "object",
            "properties": {
              "maxLimit": {
                "type": "integer",
                "minimum": 1,
                "$comment": "ADR 0002 section 10"
              },
              "defaultLimit": {
                "type": "integer",
                "minimum": 1,
                "$comment": "ADR 0002 section 10"
              },
              "overLimit": {
                "enum": [
                  "reject",
                  "clamp"
                ],
                "$comment": "ADR 0002 section 10"
              },
              "token": {
                "enum": [
                  "opaque",
                  "instant"
                ],
                "$comment": "ADR 0002 section 10"
              },
              "$include": {
                "$ref": "common.schema.json#/$defs/include"
              }
            },
            "additionalProperties": false
          }
        },
        "else": {
          "title": "alternatives",
          "description": "a string or a mapping",
          "type": "object"
        }
      }
    },
    "sortable": {
      "type": "array",
      "items": {
        "if": {
          "type": "string"
        },
        "then": {
          "type": "string",
          "minLength": 1
        },
        "else": {
          "if": {
            "type": "object"
          },
          "then": {
            "type": "object",
            "properties": {
              "key": {
                "type": "string",
                "minLength": 1,
                "$comment": "ADR 0002 section 10"
              },
              "right": {
                "$ref": "common.schema.json#/$defs/rightName",
                "$comment": "ADR 0002 section 10"
              },
              "$include": {
                "$ref": "common.schema.json#/$defs/include"
              }
            },
            "additionalProperties": false,
            "if": {
              "properties": {
                "$include": true
              },
              "required": [
                "$include"
              ]
            },
            "else": {
              "properties": {
                "key": true
              },
              "required": [
                "key"
              ]
            }
          },
          "else": {
            "title": "alternatives",
            "description": "a string or a mapping",
            "type": "object"
          }
        }
      },
      "description": "Sort keys: an item field, or { key, right } (ADR 0002 section 10)."
    },
    "responses": {
      "type": "object",
      "description": "Success (200 to 299) and redirect (301, 302, 303, 307, 308) responses.",
      "properties": {
        "$include": {
          "$ref": "common.schema.json#/$defs/include"
        }
      },
      "propertyNames": {
        "description": "a success or redirect status (ADR 0002 section 7)",
        "pattern": "^(?:2[0-9][0-9]|30[1237]|308|\\$include)$",
        "not": {
          "enum": [
            "__proto__",
            "constructor",
            "prototype"
          ]
        }
      },
      "additionalProperties": {
        "type": "object",
        "properties": {
          "body": {
            "$ref": "schema.schema.json#/$defs/schema",
            "$comment": "ADR 0002 section 7"
          },
          "headers": {
            "$ref": "#/$defs/fields",
            "$comment": "ADR 0002 section 7",
            "description": "Response headers: a fields map keyed by name."
          },
          "description": {
            "$ref": "common.schema.json#/$defs/description",
            "$comment": "ADR 0002 section 7"
          },
          "$include": {
            "$ref": "common.schema.json#/$defs/include"
          }
        },
        "additionalProperties": false
      },
      "minProperties": 1
    },
    "examples": {
      "type": "object",
      "properties": {
        "$include": {
          "$ref": "common.schema.json#/$defs/include"
        }
      },
      "propertyNames": {
        "description": "an example name (ADR 0002 section 4)",
        "pattern": "^(?:[a-z][A-Za-z0-9_]*|\\$include)$",
        "not": {
          "enum": [
            "__proto__",
            "constructor",
            "prototype"
          ]
        }
      },
      "additionalProperties": {
        "type": "object",
        "properties": {
          "status": {
            "type": "integer",
            "minimum": 200,
            "maximum": 399,
            "$comment": "ADR 0002 section 12"
          },
          "request": {
            "const": true,
            "$comment": "ADR 0002 section 12"
          },
          "error": {
            "$ref": "common.schema.json#/$defs/errorCode",
            "$comment": "ADR 0002 section 12",
            "enum": [
              "api.csrf_invalid",
              "api.cursor_too_old",
              "api.deadline_exceeded",
              "api.forbidden",
              "api.idempotency_in_progress",
              "api.idempotency_key_reused",
              "api.internal",
              "api.not_found",
              "api.payload_too_large",
              "api.precondition_failed",
              "api.precondition_required",
              "api.rate_limited",
              "api.schema_invalid",
              "api.service_unavailable",
              "api.sort_key_forbidden",
              "api.unauthenticated",
              "api.unsupported_media_type",
              "api.upstream_timeout",
              "api.upstream_unavailable",
              "state.conflict"
            ],
            "enumDescriptions": [
              "Supplied by seampact: the default code of the csrfInvalid role.",
              "Supplied by seampact: the default code of the gone role.",
              "Supplied by seampact: the default code of the deadlineExceeded role.",
              "Supplied by seampact: the default code of the forbidden role.",
              "Supplied by seampact: the default code of the idempotencyInProgress role.",
              "Supplied by seampact: the default code of the idempotencyKeyReused role.",
              "Supplied by seampact: the default code of the undeclaredStatus role.",
              "Supplied by seampact: the default code of the notFound role.",
              "Supplied by seampact: the default code of the payloadTooLarge role.",
              "Supplied by seampact: the default code of the preconditionFailed role.",
              "Supplied by seampact: the default code of the preconditionRequired role.",
              "Supplied by seampact: the default code of the rateLimited role.",
              "Supplied by seampact: the default code of the schemaInvalid role.",
              "Supplied by seampact: the default code of the serviceUnavailable role.",
              "Supplied by seampact: the default code of the sortKeyForbidden role.",
              "Supplied by seampact: the default code of the unauthenticated role.",
              "Supplied by seampact: the default code of the unsupportedMediaType role.",
              "Supplied by seampact: the default code of the upstreamTimeout role.",
              "Supplied by seampact: the default code of the upstreamUnavailable role.",
              "Supplied by seampact: the default code of the stateConflict role."
            ]
          },
          "value": {
            "title": "data",
            "$comment": "ADR 0002 section 12",
            "description": "The payload, the request body or the code's params."
          },
          "$include": {
            "$ref": "common.schema.json#/$defs/include"
          }
        },
        "additionalProperties": false,
        "if": {
          "properties": {
            "$include": true
          },
          "required": [
            "$include"
          ]
        },
        "else": {
          "properties": {
            "value": true
          },
          "required": [
            "value"
          ]
        }
      }
    }
  }
}

contract/.seampact/schemas/pack.schema.j.text:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "seampact pack file",
  "type": "object",
  "description": "A convention pack: data only, the keys of a base plus its manifest and derive entries (ADR 0002 section 2, ADR 0008).",
  "properties": {
    "pack": {
      "$ref": "#/$defs/manifest",
      "$comment": "ADR 0002 section 2"
    },
    "schemas": {
      "$ref": "schemas.schema.json",
      "$comment": "ADR 0002 section 1",
      "description": "Named schemas, in the schema language of ADR 0003."
    },
    "enums": {
      "$ref": "enums.schema.json",
      "$comment": "ADR 0002 section 12",
      "description": "Enums: values, source, reason, fallback (ADR 0002 section 12)."
    },
    "scalars": {
      "$ref": "scalars.schema.json",
      "$comment": "ADR 0003 section 8",
      "description": "Named formats: a base type plus portable refinements (ADR 0003 section 8)."
    },
    "errors": {
      "$ref": "errors.schema.json",
      "$comment": "ADR 0002 section 11",
      "description": "Error codes, declared once (ADR 0002 section 11)."
    },
    "natures": {
      "$ref": "natures.schema.json",
      "$comment": "ADR 0002 section 11",
      "description": "Error natures, each mapped onto a base nature (ADR 0002 section 11)."
    },
    "schemes": {
      "$ref": "schemes.schema.json",
      "$comment": "ADR 0002 section 9",
      "description": "Security schemes (ADR 0002 section 9)."
    },
    "headers": {
      "$ref": "headers.schema.json",
      "$comment": "ADR 0002 section 9",
      "description": "Identity headers (ADR 0002 section 9)."
    },
    "identities": {
      "$ref": "identities.schema.json",
      "$comment": "ADR 0002 section 9",
      "description": "Identities (ADR 0002 section 9)."
    },
    "rights": {
      "$ref": "rights.schema.json",
      "$comment": "ADR 0002 section 9",
      "description": "Rights (ADR 0002 section 9)."
    },
    "rules": {
      "$ref": "rules.schema.json",
      "$comment": "ADR 0002 section 9",
      "description": "Rules: pre-handler checks that are not rights (ADR 0002 section 9)."
    },
    "requirements": {
      "$ref": "requirements.schema.json",
      "$comment": "ADR 0002 section 9",
      "description": "Named requirement items (ADR 0002 section 9)."
    },
    "scopes": {
      "$ref": "scopes.schema.json",
      "$comment": "ADR 0002 section 9",
      "description": "Tenancy scopes (ADR 0002 section 9)."
    },
    "buckets": {
      "$ref": "buckets.schema.json",
      "$comment": "ADR 0002 section 9",
      "description": "Rate-limit buckets (ADR 0002 section 9)."
    },
    "services": {
      "$ref": "services.schema.json",
      "$comment": "ADR 0002 section 10",
      "description": "Upstream services (ADR 0002 section 10)."
    },
    "pagings": {
      "$ref": "pagings.schema.json",
      "$comment": "ADR 0002 section 14",
      "description": "Paging styles (ADR 0002 section 14)."
    },
    "formats": {
      "$ref": "formats.schema.json",
      "$comment": "ADR 0002 section 13",
      "description": "Wire formats (ADR 0002 section 13)."
    },
    "conventions": {
      "$ref": "conventions.schema.json",
      "$comment": "ADR 0002 section 13"
    },
    "extensions": {
      "$ref": "base.schema.json#/$defs/extensions",
      "$comment": "ADR 0002 section 12"
    },
    "lint": {
      "$ref": "common.schema.json#/$defs/lintRules",
      "$comment": "ADR 0002 section 12"
    },
    "derive": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/entry"
      },
      "$comment": "ADR 0002 section 2",
      "description": "Derivation entries, applied in order."
    },
    "$include": {
      "$ref": "common.schema.json#/$defs/include"
    }
  },
  "additionalProperties": false,
  "if": {
    "properties": {
      "$include": true
    },
    "required": [
      "$include"
    ]
  },
  "else": {
    "properties": {
      "pack": true
    },
    "required": [
      "pack"
    ]
  },
  "$defs": {
    "manifest": {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "minLength": 1,
          "$comment": "ADR 0002 section 2",
          "description": "The package name, or a name of the contract's choosing."
        },
        "version": {
          "type": "string",
          "pattern": "^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)(?:-[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?(?:\\+[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?$",
          "$comment": "ADR 0002 section 2",
          "description": "The pack's semver version."
        },
        "extends": {
          "type": "array",
          "items": {
            "title": "pack reference",
            "description": "A path starting with ./ or ../, or a package name (ADR 0002 section 2).",
            "type": "string",
            "pattern": "^[^\\u0000-\\u001F\\u007F-\\u009F\\u061C\\u200E\\u200F\\u202A-\\u202E\\u2066-\\u2069\\u2028\\u2029]+$"
          },
          "$comment": "ADR 0002 section 2",
          "description": "Packs applied just before this one."
        },
        "$include": {
          "$ref": "common.schema.json#/$defs/include"
        }
      },
      "additionalProperties": false,
      "if": {
        "properties": {
          "$include": true
        },
        "required": [
          "$include"
        ]
      },
      "else": {
        "properties": {
          "name": true,
          "version": true
        },
        "required": [
          "name",
          "version"
        ]
      }
    },
    "entry": {
      "type": "object",
      "title": "derive entry",
      "properties": {
        "entry": {
          "$ref": "common.schema.json#/$defs/name",
          "$comment": "ADR 0002 section 2",
          "description": "The entry's name, unique in the pack."
        },
        "select": {
          "type": "object",
          "properties": {
            "op": {
              "type": "array",
              "items": {
                "enum": [
                  "list",
                  "get",
                  "create",
                  "update",
                  "delete",
                  "batch"
                ]
              },
              "minItems": 1,
              "$comment": "ADR 0008"
            },
            "access": {
              "type": "array",
              "items": {
                "enum": [
                  "read",
                  "write"
                ]
              },
              "minItems": 1,
              "$comment": "ADR 0008"
            },
            "apiKind": {
              "type": "array",
              "items": {
                "enum": [
                  "product",
                  "service"
                ]
              },
              "minItems": 1,
              "$comment": "ADR 0008"
            },
            "identity": {
              "type": "array",
              "items": {
                "$ref": "common.schema.json#/$defs/name"
              },
              "minItems": 1,
              "$comment": "ADR 0008"
            },
            "tag": {
              "type": "array",
              "items": {
                "type": "string",
                "minLength": 1
              },
              "minItems": 1,
              "$comment": "ADR 0008"
            },
            "$include": {
              "$ref": "common.schema.json#/$defs/include"
            }
          },
          "additionalProperties": false,
          "$comment": "ADR 0002 section 2"
        },
        "declareRight": {
          "type": "object",
          "properties": {
            "name": {
              "type": "string",
              "minLength": 1,
              "$comment": "ADR 0002 section 2",
              "description": "A template over {resource} and {op}."
            },
            "subject": {
              "type": "object",
              "properties": {
                "member": {
                  "enum": [
                    "resource",
                    "none"
                  ],
                  "$comment": "ADR 0002 section 2"
                },
                "collection": {
                  "enum": [
                    "innermostScope",
                    "none"
                  ],
                  "$comment": "ADR 0002 section 2"
                },
                "$include": {
                  "$ref": "common.schema.json#/$defs/include"
                }
              },
              "additionalProperties": false,
              "$comment": "ADR 0002 section 2"
            },
            "errors": {
              "$ref": "common.schema.json#/$defs/errorCodes",
              "$comment": "ADR 0002 section 2",
              "items": {
                "enum": [
                  "api.csrf_invalid",
                  "api.cursor_too_old",
                  "api.deadline_exceeded",
                  "api.forbidden",
                  "api.idempotency_in_progress",
                  "api.idempotency_key_reused",
                  "api.internal",
                  "api.not_found",
                  "api.payload_too_large",
                  "api.precondition_failed",
                  "api.precondition_required",
                  "api.rate_limited",
                  "api.schema_invalid",
                  "api.service_unavailable",
                  "api.sort_key_forbidden",
                  "api.unauthenticated",
                  "api.unsupported_media_type",
                  "api.upstream_timeout",
                  "api.upstream_unavailable",
                  "state.conflict"
                ],
                "enumDescriptions": [
                  "Supplied by seampact: the default code of the csrfInvalid role.",
                  "Supplied by seampact: the default code of the gone role.",
                  "Supplied by seampact: the default code of the deadlineExceeded role.",
                  "Supplied by seampact: the default code of the forbidden role.",
                  "Supplied by seampact: the default code of the idempotencyInProgress role.",
                  "Supplied by seampact: the default code of the idempotencyKeyReused role.",
                  "Supplied by seampact: the default code of the undeclaredStatus role.",
                  "Supplied by seampact: the default code of the notFound role.",
                  "Supplied by seampact: the default code of the payloadTooLarge role.",
                  "Supplied by seampact: the default code of the preconditionFailed role.",
                  "Supplied by seampact: the default code of the preconditionRequired role.",
                  "Supplied by seampact: the default code of the rateLimited role.",
                  "Supplied by seampact: the default code of the schemaInvalid role.",
                  "Supplied by seampact: the default code of the serviceUnavailable role.",
                  "Supplied by seampact: the default code of the sortKeyForbidden role.",
                  "Supplied by seampact: the default code of the unauthenticated role.",
                  "Supplied by seampact: the default code of the unsupportedMediaType role.",
                  "Supplied by seampact: the default code of the upstreamTimeout role.",
                  "Supplied by seampact: the default code of the upstreamUnavailable role.",
                  "Supplied by seampact: the default code of the stateConflict role."
                ]
