                "not": {}
              }
            }
          },
          "else": {
            "if": {
              "properties": {
                "$include": true
              },
              "required": [
                "$include"
              ]
            },
            "else": {
              "title": "choice",
              "description": "a right ({ right: <template> }) or a rule ({ rule, params, bucket })",
              "properties": {
                "rule": true
              },
              "required": [
                "rule"
              ]
            }
          },
          "$comment": "ADR 0002 section 2"
        },
        "attachErrors": {
          "$ref": "common.schema.json#/$defs/errorCodes",
          "$comment": "ADR 0002 section 2",
          "items": {
            "enum": [
              "api.csrf_invalid",
              "api.cursor_too_old",
              "api.deadline_exceeded",
              "api.forbidden",
              "api.idempotency_in_progress",
              "api.idempotency_key_reused",
              "api.internal",
              "api.not_found",
              "api.payload_too_large",
              "api.precondition_failed",
              "api.precondition_required",
              "api.rate_limited",
              "api.schema_invalid",
              "api.service_unavailable",
              "api.sort_key_forbidden",
              "api.unauthenticated",
              "api.unsupported_media_type",
              "api.upstream_timeout",
              "api.upstream_unavailable",
              "state.conflict"
            ],
            "enumDescriptions": [
              "Supplied by seampact: the default code of the csrfInvalid role.",
              "Supplied by seampact: the default code of the gone role.",
              "Supplied by seampact: the default code of the deadlineExceeded role.",
              "Supplied by seampact: the default code of the forbidden role.",
