    "reference": {
      "title": "schema reference",
      "description": "A schema name (Task) or a file (./schemas/task.yaml#/Task) (ADR 0002 section 2).",
      "type": "string",
      "pattern": "^(?:[A-Z][A-Za-z0-9]*|\\.\\.?/[^\\\\#\\u0000-\\u001F\\u007F-\\u009F\\u061C\\u200E\\u200F\\u202A-\\u202E\\u2066-\\u2069\\u2028\\u2029]+(?:#/[^\\u0000-\\u001F\\u007F-\\u009F\\u061C\\u200E\\u200F\\u202A-\\u202E\\u2066-\\u2069\\u2028\\u2029]*)?)$",
      "anyOf": [
        {
          "enum": [
            "Note",
            "NoteId"
          ],
          "enumDescriptions": [
            "Declared in api.yaml line 24.",
            "Declared in api.yaml line 23."
          ]
        },
        {
          "pattern": "^\\.\\.?/"
        }
      ]
    },
    "mapping": {
      "type": "object",
      "if": {
        "properties": {
          "$ref": true
        },
        "required": [
          "$ref"
        ]
      },
      "then": {
        "$ref": "#/$defs/referenceMapping"
      },
      "else": {
        "if": {
          "properties": {
            "pick": true
          },
          "required": [
            "pick"
          ]
        },
        "then": {
          "$ref": "#/$defs/derived"
        },
        "else": {
          "if": {
            "properties": {
              "omit": true
            },
            "required": [
              "omit"
            ]
