            "not": {}
          },
          "else": {
            "if": {
              "type": "string"
            },
            "then": {
              "$ref": "common.schema.json#/$defs/schemaName"
            },
            "else": {
              "if": {
                "type": "object"
              },
              "then": {
                "type": "object",
                "description": "A narrowing of a catalogue enum to a strict subset (ADR 0003 section 7).",
                "properties": {
                  "narrow": {
                    "$ref": "common.schema.json#/$defs/schemaName",
                    "$comment": "ADR 0003 section 7"
                  },
