          "required": [
            "kind"
          ]
        },
        "then": {
          "$ref": "#/$defs/bearer"
        },
        "else": {
          "if": {
            "properties": {
              "kind": {
                "const": "cookie"
              }
            },
            "required": [
              "kind"
            ]
          },
          "then": {
