              "Supplied by seampact: the default code of the forbidden role.",
              "Supplied by seampact: the default code of the idempotencyInProgress role.",
              "Supplied by seampact: the default code of the idempotencyKeyReused role.",
              "Supplied by seampact: the default code of the undeclaredStatus role.",
              "Supplied by seampact: the default code of the notFound role.",
              "Supplied by seampact: the default code of the payloadTooLarge role.",
              "Supplied by seampact: the default code of the preconditionFailed role.",
              "Supplied by seampact: the default code of the preconditionRequired role.",
              "Supplied by seampact: the default code of the rateLimited role.",
              "Supplied by seampact: the default code of the schemaInvalid role.",
              "Supplied by seampact: the default code of the serviceUnavailable role.",
              "Supplied by seampact: the default code of the sortKeyForbidden role.",
              "Supplied by seampact: the default code of the unauthenticated role.",
              "Supplied by seampact: the default code of the unsupportedMediaType role.",
              "Supplied by seampact: the default code of the upstreamTimeout role.",
              "Supplied by seampact: the default code of the upstreamUnavailable role.",
              "Supplied by seampact: the default code of the stateConflict role."
            ]
          }
        },
        "lint": {
          "$ref": "common.schema.json#/$defs/lintAllow",
          "$comment": "ADR 0002 section 12"
        },
        "summary": {
          "$ref": "common.schema.json#/$defs/summary",
          "$comment": "ADR 0002 section 9"
        },
        "description": {
          "$ref": "common.schema.json#/$defs/description",
          "$comment": "ADR 0002 section 9"
        },
        "$include": {
          "$ref": "common.schema.json#/$defs/include"
        }
      },
      "patternProperties": {
        "^x-seampact-": {
          "title": "reserved",
          "description": "The extension prefix 'seampact' is reserved (ADR 0008).",
          "not": {}
        },
        "^x-[a-z][a-z0-9]*-[a-z][a-z0-9]*(-[a-z0-9]+)*$": {
          "$comment": "ADR 0002 section 12"
        }
      },
      "additionalProperties": false
    }
  }
}

